import sys
pairs = {')': '(', ']': '[', '}': '{'}
lines = sys.stdin.read().split()
for s in lines[1:1 + int(lines[0])]:
    stack, ok = [], True
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                ok = False
                break
        else:
            stack.append(ch)
    print('YES' if ok and not stack else 'NO')

import sys
lines = sys.stdin.read().split()
for s in lines[1:1 + int(lines[0])]:
    last, start, best = {}, 0, 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    print(best)
